import{_ as a,o as e,c as o,a3 as r}from"./chunks/framework.DMtjdCb-.js";const s="/help/assets/first-login.Chc51MMc.png",n="/help/assets/connections.CJWiPXEx.png",i="/help/assets/connect-ani-rss.D5DCRmCi.png",u=JSON.parse('{"title":"3. 首次打开","description":"","frontmatter":{},"headers":[],"relativePath":"zh-Hans/first-use.md","filePath":"zh-Hans/first-use.md"}'),l={name:"zh-Hans/first-use.md"};function c(p,t,h,d,g,_){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="_3-首次打开" tabindex="-1">3. 首次打开 <a class="header-anchor" href="#_3-首次打开" aria-label="Permalink to &quot;3. 首次打开&quot;">​</a></h1><p>本章完成后，确认能够登录、浏览作品，并知道媒体将保存在哪里。</p><h2 id="登录" tabindex="-1">登录 <a class="header-anchor" href="#登录" aria-label="Permalink to &quot;登录&quot;">​</a></h2><ol><li>打开启动窗口或容器日志显示的 AnimeMachine 地址。</li><li>输入同一窗口中的初始用户名和随机密码，点击 <strong>登录</strong>。</li><li>保存登录信息。电脑部署的初始账户同时保存在 <code>data/state/auth/initial-admin.txt</code>。</li></ol><p><img src="'+s+'" alt="登录页面：使用启动窗口或容器日志中的账户" loading="lazy"></p><p>在 <strong>设置 → 用户</strong> 中可以创建其它账户。观看记录和隐藏作品分别随账户保存；家人使用自己的账户即可保留独立记录。</p><p>每个账户都可以修改自己的密码：管理员打开 <strong>设置 → 用户 → 修改密码</strong>，其它账户打开 <strong>设置</strong>。输入当前密码和两次新密码后确认。当前设备保持登录，其它设备使用新密码重新登录；旧的初始密码文件会在修改后移除。</p><h2 id="等待作品资料准备" tabindex="-1">等待作品资料准备 <a class="header-anchor" href="#等待作品资料准备" aria-label="Permalink to &quot;等待作品资料准备&quot;">​</a></h2><p>首次启动会下载并校验 Bangumi Archive，然后先准备当季及近期作品，其余资料在后台补全。首页状态栏会显示当前步骤；发行包预置的当季图片会在对应作品就绪后显示。</p><p>当页面已有作品时，可以先浏览、订阅和播放。历史作品、收藏目录整理和本地下载计划会在完整资料就绪后逐步可用。中途停止后，从原目录重新启动会继续准备。</p><p><strong>完成标志：</strong> 首页显示作品卡片，点击标题能够打开作品详情。图片仍在补齐时，可以继续使用已经显示的作品。</p><h2 id="确认服务连接" tabindex="-1">确认服务连接 <a class="header-anchor" href="#确认服务连接" aria-label="Permalink to &quot;确认服务连接&quot;">​</a></h2><p>打开 <strong>设置 → 连接</strong>，查看 Ani-RSS 与 qBittorrent 的连接状态。</p><p><img src="'+n+'" alt="完整组合的连接状态：检查服务是否就绪" loading="lazy"></p><p><img src="'+i+'" alt="Ani-RSS：自动配置后的连接与媒体目录" loading="lazy"></p><ul><li><strong>默认 NAS 组合：</strong> 等待服务自动连接，无需手工填写密钥。</li><li><strong>电脑部署或接入已有服务：</strong> 按页面填写服务地址与登录信息，使用连接测试确认后保存。</li><li><strong>只看已有媒体：</strong> 直接<a href="./collections.html">添加收藏目录</a>，下载服务可按需要再连接。</li></ul><p>标有 <strong>部署设置</strong> 的项目由启动配置提供，页面显示实际生效的值。默认组合保持原值即可；使用自己的已有服务时，按对应部署模板配置地址。</p><p>浏览器使用 <code>http://NAS地址:端口</code> 访问管理页面。默认组合内部使用 <code>http://ani-rss:7789</code> 和 <code>http://qbittorrent:8080</code>，这两个名称是容器之间的地址。</p><h2 id="确认保存位置" tabindex="-1">确认保存位置 <a class="header-anchor" href="#确认保存位置" aria-label="Permalink to &quot;确认保存位置&quot;">​</a></h2><p>默认 NAS 组合已映射 <code>/Library</code>、<code>/Media</code> 等目录，使用已有默认值即可。想使用硬盘上的其它目录时，先按<a href="./collections.html">已有收藏</a>确认 NAS 路径与容器路径的对应关系，再修改。</p><p>接下来<a href="./subscribe.html">订阅一部动画</a>，完成第一次下载。</p>',21)])])}const f=a(l,[["render",c]]);export{u as __pageData,f as default};
